// 2025.01.08 rev 1
// 2025.01.09 rev 2 use PI for something and code cleanup

// https://www.mimirgames.com/articles/programming/digits-of-pi-needed-for-floating-point-numbers/
#define PI 3.1415926535897932384626433832795
// HEIGHT = sqrt(3.)/2. * SIDE
// assuming SIDE == 1., HEIGHT = sqrt(3.)/2.
#define EQL_TRIG 0.86602540378

// From https://thebookofshaders.com/09/
vec2 rotate2D (vec2 _st, float _angle, float _around) {
    _st -= _around;
    _st =  mat2(cos(_angle),-sin(_angle),
                sin(_angle),cos(_angle)) * _st;
    _st += _around;
    return _st;
}

// from https://www.reedbeta.com/blog/hash-functions-for-gpu-rendering/
uint global_hash = 0u;
float pcg_hash_float(uint x)
{
    uint state = x * 747796405u + 2891336453u + global_hash;
    uint word = ((state >> ((state >> 28u) + 4u)) ^ state) * 277803737u;
    uint hashed_value = (word >> 22u) ^ word;
    global_hash = hashed_value;
    return float(hashed_value) / 4294967295.0; // 4294967295 is 2^32 - 1
}

float pcg_hash_float(float x)
{
    return pcg_hash_float(floatBitsToUint(x));
}

// Returns 1. if uv coord is inside the triangle
float simpleTrig(vec2 uv, float size, float ang) {
    vec2 uvs = rotate2D(uv, ang, 0.0) / size;
    uvs.x *= EQL_TRIG;
    return step(uvs.y/2., uvs.x) * step(uvs.y/2., EQL_TRIG - uvs.x) * step(0.0, uvs.y);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    // Generate grainy bg
    vec3 col;
    float pall = 0.11111;
    col = mix(vec3(smoothstep(uv.x * -uv.y/2., 1.0, pall) * 1.), vec3(pcg_hash_float(uv.y * uv.x)), 0.033);
    uv.x += 0.333;

    // Fract and move uv in tiles
    uv *= 7.0;
    uv = fract(vec2(
        uv.x,
        uv.y + (fract(uv.x * 0.5) > 0.5 ? fract(iTime * 1.3) : -fract(iTime * 0.977))
          )
        );

    // Fix aspect ratio
    float ar = iResolution.y/iResolution.x;
    uv.y *= ar;

    // Define hexagon size constants
    float size = 0.33;
    float size2 = size/2.0;
    float height = size * EQL_TRIG;
    uv.x -= size2;

    // Generate 6 rotated trigs
    col = mix(col, vec3(pall), simpleTrig(uv, size, 0.0));
    col = mix(col, vec3(pall*3.), simpleTrig(vec2(uv.x - size2, uv.y - height), size, 0.0));
    col = mix(col, vec3(pall*2.), simpleTrig(vec2(uv.x - size, uv.y), size, PI/3.));
    col = mix(col, vec3(pall*4.), simpleTrig(vec2(uv.x - size2, uv.y - height), size, PI/3.));
    col = mix(col, vec3(pall*5.), simpleTrig(vec2(uv.x - size2, uv.y - height), size, PI/1.5));
    col = mix(col, vec3(pall*6.), simpleTrig(vec2(uv.x - size2, uv.y - height), size, PI));


    // Output to screen
    fragColor = vec4(col,1.0);
}
